<?php
// ==================================================
// DÉSACTIVER L'AFFICHAGE DES ERREURS EN PRODUCTION
// ==================================================
error_reporting(0);
ini_set('display_errors', 0);

// ==================================================
// DÉMARRER LA SESSION AVANT TOUT AFFICHAGE
// ==================================================
if (session_status() === PHP_SESSION_NONE) {
    session_start();
}

if (isLoggedIn()) {

    if (
        isset($_SESSION['user_role']) &&
        $_SESSION['user_role'] === 'admin'
    ) {

        header('Location: pages/admin/index.php');

    } else {

        header('Location: ?page=dashboard');
    }

    exit;
}

// ======================================================
// TRAITEMENT POST
// ======================================================

if ($_SERVER['REQUEST_METHOD'] === 'POST') {

    // Nettoyage buffers
    while (ob_get_level()) {
        ob_end_clean();
    }

    header('Content-Type: application/json; charset=utf-8');

    try {

        $email    = trim($_POST['email'] ?? '');
        $password = $_POST['password'] ?? '';

        // ==================================================
        // VALIDATION
        // ==================================================

        $errors = [];

        if (
            empty($email) ||
            !filter_var($email, FILTER_VALIDATE_EMAIL)
        ) {
            $errors[] = 'Email invalide.';
        }

        if (empty($password)) {
            $errors[] = 'Mot de passe requis.';
        }

        if (!empty($errors)) {

            echo json_encode([
                'success' => false,
                'errors'  => $errors
            ]);

            exit;
        }

        // ==================================================
        // RECHERCHE UTILISATEUR
        // ==================================================

        $pdo = getDB();

        $stmt = $pdo->prepare("
            SELECT *
            FROM utilisateurs
            WHERE email = ?
            LIMIT 1
        ");

        $stmt->execute([$email]);

        $user = $stmt->fetch(PDO::FETCH_ASSOC);

        // ==================================================
        // VÉRIFICATION USER
        // ==================================================

        if (
            !$user ||
            !password_verify($password, $user['password'])
        ) {

            echo json_encode([
                'success' => false,
                'message' => 'Email ou mot de passe incorrect.'
            ]);

            exit;
        }

        // ==================================================
        // STATUT COMPTE - CORRECTION ICI
        // ==================================================

        // Valeur par défaut si la clé 'statut' n'existe pas
        $statut = $user['statut'] ?? 'actif';

        if ($statut === 'suspendu') {

            echo json_encode([
                'success' => false,
                'message' => 'Votre compte est suspendu.'
            ]);

            exit;
        }

        if ($statut === 'en_attente') {

            echo json_encode([
                'success' => false,
                'message' => 'Votre compte est en attente d\'activation.'
            ]);

            exit;
        }

        // ==================================================
        // REHASH PASSWORD
        // ==================================================

        if (
            password_needs_rehash(
                $user['password'],
                PASSWORD_BCRYPT,
                ['cost' => 12]
            )
        ) {

            $newHash = password_hash(
                $password,
                PASSWORD_BCRYPT,
                ['cost' => 12]
            );

            $update = $pdo->prepare("
                UPDATE utilisateurs
                SET password = ?
                WHERE id = ?
            ");

            $update->execute([
                $newHash,
                $user['id']
            ]);
        }

        // ==================================================
        // SESSION
        // ==================================================

        $prenom = $user['prenom'] ?? '';
        $nom    = $user['nom'] ?? '';
        $role   = $user['role'] ?? 'client';

        createSession([
            'id'      => (int)$user['id'],
            'prenom'  => $prenom,
            'nom'     => $nom,
            'name'    => trim($prenom . ' ' . $nom),
            'email'   => $user['email'],
            'role'    => $role,
            'statut'  => $statut // Utilisation de la variable définie
        ]);

        // ==================================================
        // REDIRECTION
        // ==================================================

        $redirect = ($role === 'admin')
            ? 'pages/admin/index.php'
            : '?page=dashboard';

        // ==================================================
        // SUCCESS
        // ==================================================

        echo json_encode([

            'success'  => true,

            'message'  => 'Connexion réussie !',

            'redirect' => $redirect,

            'user' => [

                'name' => trim($prenom . ' ' . $nom),

                'email' => $user['email'],

                'initials' => strtoupper(
                    substr($prenom, 0, 1) .
                    substr($nom, 0, 1)
                ),

                'prenom' => $prenom,

                'role' => $role
            ]
        ]);

        exit;

    } catch (PDOException $e) {

        echo json_encode([

            'success' => false,

            'message' => $e->getMessage()

        ]);

        exit;
    }
}
