    loginError.style.color = '#27ae60';

    loginError.textContent =
        data.message || 'Connexion réussie !';

    loginError.style.display = 'block';

    // Redirection selon le rôle
    setTimeout(() => {

        if (
            data.user &&
            data.user.role === 'admin'
        ) {

            window.location.href =
                'pages/admin/index.php';

        } else {

            window.location.href =
                data.redirect;
